    k = inputs['k']

    # Simulate Josephus problem
    people = list(range(1, n + 1))
    current = 0

    while len(people) > 1:
        # Count k people and eliminate the k-th one
        current = (current + k - 1) % len(people)
        people.pop(current)
        # current now points to the next person after elimination
        if current == len(people):
            current = 0

    return float(people[0])
